    const amrex::Real qf = k_f * (sc[1] * sc[2]);
    const amrex::Real qr =
        k_f * exp(-(g_RT[1] + g_RT[2] - g_RT[3] - g_RT[4])) * (sc[3] * sc[4]);
    const amrex::Real qdot = qf - qr;
    wdot[1] -= qdot;
    wdot[2] -= qdot;
