    J[8] += dqdci; // dwdot[CH4]/d[H2]
    // d()/d[H]
    dqdci = +k_f * sc[7];
    J[15] -= dqdci; // dwdot[H]/d[H]
    J[21] -= dqdci; // dwdot[CH3]/d[H]
    J[22] += dqdci; // dwdot[CH4]/d[H]
