  // reverse
  phi_r = sc[0] * sc[9];
  Kc = refC * exp(-g_RT[0] - g_RT[9] + g_RT[11]);
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[11]) + (h_RT[0] + h_RT[9]) - 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
