    dqdci = (6 - 1) * dcdc_fac;
    J[84] += dqdci; // dwdot[H2]/d[H2O]
    J[93] += dqdci; // dwdot[CO]/d[H2O]
    J[95] -= dqdci; // dwdot[CH2O]/d[H2O]
