    J[137] -= dqdci; // dwdot[CH2O]/d[CO]
    // d()/d[CO2]
    dqdci = (2 - 1) * dcdc_fac;
    J[140] += dqdci; // dwdot[H2]/d[CO2]
    J[149] += dqdci; // dwdot[CO]/d[CO2]
    J[151] -= dqdci; // dwdot[CH2O]/d[CO2]
    // d()/d[CH2O]
    dqdci = (2.5 - 1) * dcdc_fac + k_f;
    J[154] += dqdci; // dwdot[H2]/d[CH2O]
    J[163] += dqdci; // dwdot[CO]/d[CH2O]
