    dqdc[2] = dcdc_fac;
    dqdc[3] = dcdc_fac;
    dqdc[4] = dcdc_fac;
    dqdc[5] = dcdc_fac;
    dqdc[6] = 6 * dcdc_fac;
    dqdc[7] = dcdc_fac;
    dqdc[8] = 2 * dcdc_fac;
    dqdc[9] = 1.5 * dcdc_fac - k_r * sc[0];
