    J[9] -= dqdci;  // dwdot[CO]/d[H2]
    J[10] += dqdci; // dwdot[CO2]/d[H2]
    // d()/d[O]
    dqdci = +k_f * sc[9];
    J[45] -= dqdci; // dwdot[O]/d[O]
    J[51] -= dqdci; // dwdot[CO]/d[O]
    J[52] += dqdci; // dwdot[CO2]/d[O]
    // d()/d[H2O]
    dqdci = (12 - 1) * dcdc_fac;
    J[87] -= dqdci; // dwdot[O]/d[H2O]
    J[93] -= dqdci; // dwdot[CO]/d[H2O]
    J[94] += dqdci; // dwdot[CO2]/d[H2O]
