    dqdci = (2 - 1) * dcdc_fac;
    J[115] -= dqdci; // dwdot[O]/d[CH4]
    J[121] -= dqdci; // dwdot[CO]/d[CH4]
    J[122] += dqdci; // dwdot[CO2]/d[CH4]
