  // forward
  phi_f = sc[0];
  k_f = 45800000000000 * exp(-1.4 * logT - (52530.7877433547) * invT);
  dlnkfdT = -1.4 * invT + (52530.7877433547) * invT2;
  // reverse
  phi_r = (sc[1] * sc[1]);
