    dqdc[6] = 12 * q_nocor;
    dqdc[7] = q_nocor;
    dqdc[8] = 2 * q_nocor;
    dqdc[9] = 1.9 * q_nocor;
    dqdc[10] = 3.8 * q_nocor;
    dqdc[11] = 2.5 * q_nocor;
