  Kc = refC * exp(-g_RT[1] - g_RT[4] + g_RT[6]);
  k_r = k_f / Kc;
  dlnKcdT =
      invT * (-(2.000000 * h_RT[6]) + (h_RT[1] + h_RT[4] + h_RT[6]) - 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
