  // reaction 34: CH2O + H => CO + H2 + H
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[1] * sc[11];
  k_f = 11400000 * exp(0.582 * logT - (7243.80390425894) * invT);
